'use client';

import React from 'react';
import * as THREE from 'three';
import { PlantItem } from '@/types/aquarium';

interface PlantFieldProps {
  tankBounds: THREE.Vector3;
  plantsConfig?: PlantItem[];
  groundLevelY?: number;
}

export default function PlantField({
  tankBounds,
  plantsConfig = [],
  groundLevelY,
}: PlantFieldProps) {
  const baseBottom = -tankBounds.y / 2;
  const effectiveGroundY = groundLevelY !== undefined ? groundLevelY : baseBottom + 0.08;

  if (!plantsConfig || plantsConfig.length === 0) return null;

  return (
    <group name="plant-field">
      {plantsConfig.map((plant) =>
        plant.positions?.map((pos, idx) => (
          <group key={`${plant.id}-${idx}`} position={[pos[0], effectiveGroundY, pos[2]]}>
            <mesh position={[0, 0.4, 0]} castShadow>
              <coneGeometry args={[0.35, 0.9, 6]} />
              <meshStandardMaterial
                color={plant.id === 'anubias' ? '#15803d' : '#991b1b'}
                roughness={0.6}
                metalness={0.1}
              />
            </mesh>
            <mesh position={[0.2, 0.2, 0.1]} rotation={[0, 0, 0.3]}>
              <sphereGeometry args={[0.22, 8, 8]} />
              <meshStandardMaterial
                color={plant.id === 'anubias' ? '#16a34a' : '#b91c1c'}
                roughness={0.5}
              />
            </mesh>
            <mesh position={[-0.2, 0.25, -0.1]} rotation={[0, 0, -0.3]}>
              <sphereGeometry args={[0.2, 8, 8]} />
              <meshStandardMaterial
                color={plant.id === 'anubias' ? '#22c55e' : '#dc2626'}
                roughness={0.5}
              />
            </mesh>
          </group>
        ))
      )}
    </group>
  );
}